package java.util.logging;
public class Logger { private final String name;private Level level=Level.INFO; protected Logger(String name,String resourceBundleName){this.name=name;} public static Logger getLogger(String name){return new Logger(name,null);} public static Logger getLogger(String name,String resourceBundleName){return new Logger(name,resourceBundleName);} public String getName(){return name;} public void setLevel(Level l){level=l;} public Level getLevel(){return level;} public boolean isLoggable(Level l){return l.intValue()>=(level==null?Level.INFO:level).intValue();} public void log(Level l,String message){if(isLoggable(l))System.err.println(name+": "+message);} public void log(Level l,String message,Throwable t){log(l,message);if(isLoggable(l)&&t!=null)t.printStackTrace();} public void info(String message){log(Level.INFO,message);} public void warning(String message){log(Level.WARNING,message);} public void severe(String message){log(Level.SEVERE,message);} public void fine(String message){log(Level.FINE,message);} }
